    Hyperplane_4 hyperplane = rt.geometric_traits().hyperplane_4_object()(vertices[0], vertices[1], vertices[2], vertices[3]);

    // Extract the normal vector (a, b, c, d) where the hyperplane equation is a*x + b*y + c*z + d*w + e = 0
    Vector_4 normal = hyperplane.orthogonal_vector();

    // The velocity is the negative ratio of the spatial components to the time component
    // v = - (a, b, c) / d
    double d = normal.w();
    if (std::abs(d) < 1e-10) {
        // Handle degenerate case (nearly vertical hyperplane)
        return Vector(0.0, 0.0, 0.0);
    }

    return Vector(-normal.x() / d, -normal.y() / d, -normal.z() / d);

